var RIDDLES=[
 {q:'什么东西越洗越脏？',a:'水'},
 {q:'什么布剪不断？',a:'瀑布'},
 {q:'什么车寸步难行？',a:'风车'},
 {q:'什么蛋打不烂、煮不熟、更不能吃？',a:'脸蛋'},
 {q:'什么动物你打死了它，却流了你的血？',a:'蚊子'},
 {q:'什么天气越热，它爬得越高？',a:'温度计'},
 {q:'什么人始终不敢洗澡？',a:'泥人'},
 {q:'什么东西明明是你的，别人却用得比你多？',a:'你的名字'},
 {q:'什么书你不能在书店买到？',a:'遗书'},
 {q:'什么伞永远撑不开？',a:'降落伞（不打开）'},
 {q:'什么海没有水？',a:'人海／火海'},
 {q:'什么帽不能戴？',a:'螺帽'},
 {q:'什么船从来不下水？',a:'宇宙飞船'},
 {q:'什么锁没有孔？',a:'心锁'},
 {q:'什么桥下没有水？',a:'立交桥'},
 {q:'什么河里没有鱼？',a:'银河'},
 {q:'什么线可望不可即？',a:'地平线'},
 {q:'什么门永远关不上？',a:'球门'},
 {q:'什么光看不见？',a:'时光'},
 {q:'什么官不拿工资？',a:'新郎官'}
];
function pick(seed){ var r=rngFactory(seed); var i=Math.floor(r()*RIDDLES.length); return RIDDLES[i]; }
function check(riddle,ans){ return ans.replace(/\s/g,'').indexOf(riddle.a.replace(/\s/g,''))>=0; }
var EXPORTS={pick:pick,check:check,RIDDLES:RIDDLES};


function rngFactory(seed){ var s=(seed>>>0)||1; return function(){ s=(s*1664525+1013904223)>>>0; return s/4294967296; }; }

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.RiddleForgePure = EXPORTS; }
